mapper.select:
select bb.bill_id billId, be.employee_name employeeName, DATE_FORMAT(bb.order_date, '%Y-%m-%d %H:%i:%s') orderDate, bb.order_num orderNum, bp.name, bp.mobile, IFNULL(bb.privilege_amount + bb.actual_amount,0) originalPrice, IFNULL(bb.privilege_amount,0) privilegeAmount, IFNULL(bb.actual_amount,0) actualAmount, IFNULL(bb.received_amount,0) receivedAmount, IFNULL(bb.debt_amount,0) debtAmount from base_bill bb join base_patient bp on bp.patient_id = bb.patient_id join base_treatment_process btpr on btpr.patient_id = bp.patient_id join base_employee be on btpr.registered_dentist_id = be.user_id
bb.debt_amount > 0
AND bb.org_id = #{form.orgId}
and DATE_FORMAT(bb.order_date, "%Y-%m-%d") >= DATE_FORMAT(#{form.startDate}, "%Y-%m-%d") and DATE_FORMAT(bb.order_date, "%Y-%m-%d") < DATE_FORMAT(#{form.endDate}, "%Y-%m-%d")
AND btpr.registered_dentist_id in
#{registeredDentistId}
AND bp.patient_id in
#{ids}
group by bb.order_date asc

SELECT bor.orderDate, bor.billId, bor.orderNum, bor.billNum, bor.patientId, bor.patientName, bor.mobile, bor.gender, bor.regDentistId, bor.regDentistName, IFNULL(bor.orderAmount,0) orderAmount, IFNULL(bor.privilegeAmount,0) privilegeAmount, IFNULL(bor.actualAmount,0) actualAmount, IFNULL(bor.receivedAmount,0) receivedAmount, bor.chargeStatus, bor.billerId, bor.biller FROM ( SELECT bb.org_id as orgId, DATE_FORMAT( bb.order_date, '%Y-%m-%d' ) AS orderDate, bb.bill_id AS billId, bb.order_num AS orderNum, bb.bill_num AS billNum, bb.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile AS mobile, bp.gender AS gender, btp.registered_dentist_id AS regDentistId, btp.employee_name AS regDentistName, bb.order_amount AS orderAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, IF ( bb.bill_num = NULL OR '', 0, 1 ) AS chargeStatus, bb.biller_id AS billerId, be.employee_name AS biller FROM base_bill bb LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id, be.employee_name FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) btp ON bb.treatment_id = btp.treatment_id LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN base_employee be ON bb.biller_id = be.user_id ) bor
and bor.orgId = #{query.orgId}
and bor.orderNum like concat('%', #{query.orderNum} ,'%')
and bor.billNum like concat('%', #{query.billNum} ,'%')
and concat(IFNULL(bor.patientName, ''), IFNULL(bor.pinyinName, ''), IFNULL(bor.mobile, '')) like concat('%', #{query.keyWord}, '%')
and bor.orderDate >= #{query.orderStartDate}
and bor.orderDate <= #{query.orderEndDate}
and bor.regDentistId in
#{item}
ORDER BY bor.orderDate DESC

SELECT billId, orgId, DATE_FORMAT(orderDate, '%Y-%m-%d') orderDate, DATE_FORMAT(billDate, '%Y-%m-%d') billDate, billNum, patientId, patientName, mobile, regDentistId, regDentistName, IFNULL(totalOriginalAmount,0) totalOriginalAmount, IFNULL(totalActualAmount,0) totalActualAmount, IFNULL(billReceivableAmount,0) billReceivableAmount FROM ( SELECT bb.bill_id AS billId, bb.org_id as orgId, bb.bill_date AS billDate, bb.order_date AS orderDate, bb.bill_num AS billNum, bb.patient_id AS patientId, btp.`name` AS patientName, btp.pinyin_name as pinyinName, btp.mobile AS mobile, btp.registered_dentist_id AS regDentistId, btp.employee_name AS regDentistName, bb.order_amount AS totalOriginalAmount, bb.actual_amount AS totalActualAmount, bb.debt_amount AS billReceivableAmount FROM base_bill bb LEFT JOIN ( SELECT btp.treatment_id as treatment_id, any_value(btp.patient_id) as patient_id, any_value(bp.`name`) as name, any_value(bp.mobile) as mobile, any_value(bp.gender) as gender, any_value(bp.pinyin_name) as pinyin_name, any_value(btp.registered_dentist_id) as registered_dentist_id, any_value(be.employee_name) as employee_name FROM base_treatment_process btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treatment_id IS NOT NULL GROUP BY btp.treatment_id ) btp ON bb.treatment_id = btp.treatment_id ) brr
brr.billReceivableAmount>0
and brr.orgId = #{query.orgId}
AND date_format(brr.billDate, '%Y-%m-%d') = #{query.billDate}
AND date_format(brr.orderDate, '%Y-%m-%d') = #{query.orderDate}
and concat(IFNULL(brr.patientName, ''), IFNULL(brr.pinyinName, ''), IFNULL(brr.mobile, '')) like concat('%', #{query.keyword}, '%')
and brr.regDentistId in
#{item}
order by brr.billReceivableAmount desc

SELECT IFNULL(SUM( bb.totalOriginalAmount ), 0 ) AS totalOriginalAmount, IFNULL(SUM( bb.totalActualReceiveAmount ), 0) AS totalActualReceiveAmount, IFNULL(SUM( bb.totalDiscountAmount ), 0 ) AS totalDiscountAmount, IFNULL(SUM( bb.totalDebtAmount ), 0 ) AS totalDebtAmount FROM ( SELECT bb.org_id, SUM( bb.order_amount ) AS totalOriginalAmount, SUM( bb.privilege_amount ) AS totalDiscountAmount, SUM( bb.actual_amount ) AS totalActualReceiveAmount, SUM( bb.debt_amount ) AS totalDebtAmount FROM base_bill bb
AND bb.bill_num IS NOT NULL AND bb.bill_date IS NOT NULL
and DATE_FORMAT( bb.bill_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT( bb.bill_date, '%Y') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y') <= #{query.endDate}
GROUP BY bb.org_id ) bb
and bb.org_id in
#{item}

SELECT bbd.orgId, bbd.orgName, bbd.billId, bbd.billDate, bbd.billNum, bbd.patientId, bbd.patientName, bbd.mobile, bbd.originalAmount, bbd.privilegeAmount, bbd.actualAmount, bbd.receivedAmount, bbd.remainingArrears FROM ( SELECT bbd.orgId, bbd.orgName, bbd.billId, bbd.billDate, bbd.billNum, bbd.patientId, bbd.patientName, bbd.pinyinName, bbd.mobile, bbd.originalAmount, bbd.privilegeAmount, bbd.actualAmount, bbd.receivedAmount, bbd.remainingArrears FROM ( SELECT bb.org_id AS orgId, btp.registered_dentist_id, bo.abbreviation AS orgName, bb.bill_id AS billId, DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) AS billDate, bb.bill_num AS billNum, bb.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile, bb.originalAmount, bb.privilegeAmount, bb.actualAmount, bb.receivedAmount, bb.remainingArrears FROM ( SELECT bb.org_id, bb.patient_id, bb.treatment_id, bb.bill_id, bb.bill_num, bb.bill_date, bb.order_amount AS originalAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, bb.debt_amount AS remainingArrears FROM base_bill bb WHERE bb.debt_amount > 0 ) bb LEFT JOIN base_organization bo ON bb.org_id = bo.org_id LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN base_treatment_process btp ON bb.treatment_id = btp.treatment_id ) bbd
and bbd.registered_dentist_id = #{query.dentistId}
GROUP BY bbd.billId ) bbd
and bbd.billDate >= #{query.billStartDate}
and bbd.billDate <= #{query.billEndDate}
and concat(IFNULL(bbd.patientName, ''), IFNULL(bbd.pinyinName, ''), IFNULL(bbd.mobile, '')) like concat('%', #{query.keyword}, '%')

SELECT IFNULL(SUM( bb.actual_amount ), 0) AS totalActualAmountThisMonth, IFNULL(SUM( bb.privilege_amount ), 0) AS totalPrivilegeAmountThisMonth FROM base_bill bb
AND bb.bill_num IS NOT NULL AND bb.bill_date IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.order_date, '%Y-%m' ) = #{query.queryDate}

select #{query.queryDate} as currentMonth, #{query.orgId} as orgId, IFNULL(SUM( bb.actual_amount ), 0) as currentMonthTotalActualAmount, IFNULL(SUM( bb.privilege_amount ), 0) as currentMonthTotalDiscountAmount, IFNULL(SUM( bb.debt_amount ), 0) as currentMonthTotalDebtAmount from base_bill bb
AND bb.bill_date IS NOT NULL AND bb.bill_num IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) = #{query.queryDate}

SELECT bb.bill_id AS billId, DATE_FORMAT( bb.privilege_date, '%Y-%m-%d' ) AS collectDebtDate, bb.bill_date AS billDate, bb.bill_num AS billNum, bb.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, btp.regDentistId AS regDentistId, btp.regDentistName AS regDentistName, bbp.payeeId, bbp.payeeName FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.registered_id IS NOT NULL AND btp.treat_end_time IS NOT NULL ) btp ON bb.treatment_id = btp.treatment_id LEFT JOIN ( SELECT bbp.bill_id, bbp.payee_date, bbp.payee_user_id AS payeeId, be.employee_name AS payeeName FROM base_bill_pay bbp LEFT JOIN base_employee be ON bbp.payee_user_id = be.user_id ) bbp ON bb.bill_id = bbp.bill_id AND DATE_FORMAT( bb.privilege_date, '%Y-%m-%d %H:%i' ) = DATE_FORMAT( bbp.payee_date, '%Y-%m-%d %H:%i' )
AND bb.bill_num IS NOT NULL AND bb.bill_date IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.privilege_date, '%Y-%m' ) = #{query.currentMonth}
